package net.civeira.phylax.feature.observe.observedalert.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LinkVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property link of observed alert ")
  void test_link_v_o_builder() {
    Assertions.assertFalse(LinkVO.nullValue().getLink().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LinkVO.tryFrom(null).getLink().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", LinkVO.from("one").getLink().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> LinkVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LinkVO.from("one").toString());
  }
}
